import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"记忆状态与评分","description":"本页定义 FSRS 状态和评分语义。界面措辞可以翻译，状态含义不可改变。","frontmatter":{"description":"本页定义 FSRS 状态和评分语义。界面措辞可以翻译，状态含义不可改变。"},"headers":[],"relativePath":"guide/memory-state.md","filePath":"guide/memory-state.md","lastUpdated":1787830168000}'),i={name:"guide/memory-state.md"};function l(o,t,s,h,n,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="记忆状态与评分" tabindex="-1">记忆状态与评分 <a class="header-anchor" href="#记忆状态与评分" aria-label="Permalink to &quot;记忆状态与评分&quot;">​</a></h1><p>本页定义 FSRS 状态和评分语义。界面措辞可以翻译，状态含义不可改变。</p><h2 id="状态量" tabindex="-1">状态量 <a class="header-anchor" href="#状态量" aria-label="Permalink to &quot;状态量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>符号</th><th>解释</th></tr></thead><tbody><tr><td>Difficulty</td><td>D</td><td>项目的固有和个体难度，通常约束在 1–10</td></tr><tr><td>Stability</td><td>S</td><td>记忆保持的时间尺度，单位为天</td></tr><tr><td>Retrievability</td><td>R</td><td>当前时刻成功提取的估计概率</td></tr></tbody></table><p>R 随时间下降。一次复习根据评分更新 D 与 S，再由目标保持率计算下次间隔。R 是时变估计，不应作为固定字段向用户解释。</p><h2 id="四档评分" tabindex="-1">四档评分 <a class="header-anchor" href="#四档评分" aria-label="Permalink to &quot;四档评分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>评分</th><th>用户行为</th><th>调度含义</th></tr></thead><tbody><tr><td>Again</td><td>未能回忆或答案错误</td><td>进入重学，稳定度显著调整</td></tr><tr><td>Hard</td><td>回忆成功但困难或不完整</td><td>使用保守间隔</td></tr><tr><td>Good</td><td>正常回忆成功</td><td>使用标准间隔</td></tr><tr><td>Easy</td><td>快速、确定且无提示地回忆</td><td>使用更长间隔</td></tr></tbody></table><p>评分描述的是本次提取质量，不是对词条重要性的评价。不得因为“喜欢这个词”选择 Easy，也不得因为“希望多见几次”选择 Again。</p><h2 id="二元题映射" tabindex="-1">二元题映射 <a class="header-anchor" href="#二元题映射" aria-label="Permalink to &quot;二元题映射&quot;">​</a></h2><p>课程 Interaction 常只有判对与判错：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>incorrect -&gt; Again</span></span>
<span class="line"><span>correct   -&gt; Good</span></span></code></pre></div><p>部分显式分值可映射为 Hard 或 Easy。映射规则由应用层集中处理，课程 JSON 不应为同一种题型重新定义评分枚举。</p><h2 id="关键参数" tabindex="-1">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to &quot;关键参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th style="text-align:right;">默认值</th><th>影响</th></tr></thead><tbody><tr><td><code>desiredRetention</code></td><td style="text-align:right;">0.90</td><td>越高则复习更频繁</td></tr><tr><td><code>maximumIntervalDays</code></td><td style="text-align:right;">730</td><td>限制最长间隔</td></tr><tr><td><code>enableFuzzing</code></td><td style="text-align:right;"><code>true</code></td><td>对间隔施加小幅抖动，分散队列</td></tr><tr><td><code>maxSameDayFails</code></td><td style="text-align:right;">4</td><td>限制当日失败循环</td></tr><tr><td>FSRS parameters</td><td style="text-align:right;">21 个权重</td><td>控制状态更新模型</td></tr></tbody></table><p>目标保持率不是正确率目标。提高它会增加工作量。参数变化只影响调度计算，不修改课程内容。</p><h2 id="参数调整边界" tabindex="-1">参数调整边界 <a class="header-anchor" href="#参数调整边界" aria-label="Permalink to &quot;参数调整边界&quot;">​</a></h2><ul><li>普通用户优先调整目标保持率，不直接修改 21 个权重。</li><li>个性化参数需要足够且一致的复习历史。</li><li>预览计算关闭 fuzzing，以获得确定性结果。</li><li>修改最大间隔后，已有卡片不会被解释为新卡。</li><li>Official Anki 卡使用 Official scheduler 的配置和状态。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/fsrs">FSRS 复习</a></li><li><a href="/docs/guide/review-system">复习系统</a></li><li><a href="/docs/developer/local-data">本地数据模型</a></li></ul>`,19)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
